<?php
require_once __DIR__.'/v5-common.php';$device=trim((string)($_GET['device']??''));$device=substr($device,0,64);$detail=null;$readings=[];$events=[];$error='';
try{if($device==='')throw new InvalidArgumentException('Informe um dispositivo.');$db=v5db();require_once __DIR__.'/../php/iot_service.php';if(!iotTableExists($db,'iot_devices')||!iotTableExists($db,'iot_telemetry'))throw new RuntimeException('Tabelas IoT ausentes.');$st=$db->prepare('SELECT device_id,name,location,status,last_seen FROM iot_devices WHERE device_id=? LIMIT 1');$st->bind_param('s',$device);$st->execute();$detail=$st->get_result()->fetch_assoc();$st->close();if(!$detail)throw new InvalidArgumentException('Dispositivo não localizado.');$st=$db->prepare('SELECT metric,value,unit,quality_status,captured_at FROM iot_telemetry WHERE device_id=? ORDER BY captured_at DESC,id DESC LIMIT 70');$st->bind_param('s',$device);$st->execute();$readings=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();$st=$db->prepare('SELECT e.outcome,e.created_at,r.name rule_name,t.id ticket_id,t.protocol FROM sd_iot_rule_events e JOIN sd_iot_rules r ON r.id=e.rule_id LEFT JOIN sd_tickets t ON t.id=e.ticket_id WHERE e.device_id=? ORDER BY e.created_at DESC LIMIT 40');$st->bind_param('s',$device);$st->execute();$events=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();}catch(Throwable $ex){error_log('[V5 device] '.$ex->getMessage());$error=$ex instanceof InvalidArgumentException?$ex->getMessage():'Não foi possível carregar o dispositivo e sua telemetria.';}
v5head('Saúde de dispositivo');?><header class="v5-header"><div><div class="v5-kicker">IoT / Saúde do dispositivo</div><h1><?=v5e($device?:'Dispositivo')?></h1><p>Leituras recentes, comunicação e incidentes correlacionados.</p></div><a class="v5-btn" href="iot-monitoramento.php">Todos os dispositivos</a></header><?php if($error):?><p class="v5-empty" role="alert"><?=v5e($error)?></p><?php endif;?><?php if($detail):?><section class="v5-grid"><div class="v5-tile"><span>Identificação</span><strong style="font-size:1.25rem"><?=v5e($detail['name'])?></strong></div><div class="v5-tile"><span>Status cadastrado</span><strong><?=v5e($detail['status'])?></strong></div><div class="v5-tile"><span>Última comunicação</span><strong style="font-size:1rem"><?=v5e($detail['last_seen']?:'Sem registro')?></strong></div><div class="v5-tile"><span>Localização</span><strong style="font-size:1.15rem"><?=v5e($detail['location']?:'Não informada')?></strong></div></section><div class="v5-two"><section class="v5-panel"><h2>Últimas leituras (até 70)</h2><div class="v5-scroll"><table><thead><tr><th>Data</th><th>Métrica</th><th>Valor</th><th>Qualidade</th></tr></thead><tbody><?php foreach($readings as $r):?><tr><td><?=v5e($r['captured_at'])?></td><td><?=v5e($r['metric'])?></td><td><?=v5e($r['value'])?> <?=v5e($r['unit'])?></td><td><span class="v5-tag <?=$r['quality_status']==='alerta'?'v5-danger':''?>"><?=v5e($r['quality_status'])?></span></td></tr><?php endforeach;?></tbody></table></div><?php if(!$readings):?><p class="v5-empty">Nenhuma leitura disponível.</p><?php endif;?></section><section class="v5-panel"><h2>Linha do tempo dos incidentes (até 40)</h2><ol class="v5-timeline"><?php foreach($events as $ev):?><li><time><?=v5e($ev['created_at'])?></time><strong><?=v5e($ev['rule_name'])?></strong><p><?=v5e($ev['outcome']==='created'?'Chamado criado':'Evento suprimido')?></p><?php if($ev['ticket_id']):?><a href="service-desk-detalhe.php?id=<?=(int)$ev['ticket_id']?>"><?=v5e($ev['protocol'])?></a><?php endif;?></li><?php endforeach;?></ol><?php if(!$events):?><p class="v5-empty">Nenhum incidente associado.</p><?php endif;?></section></div><p class="v5-subtle">A lista mostra as leituras mais recentes, não uma curva temporal completa. Eventos suprimidos continuam visíveis. O status cadastrado não é alterado pela falta de comunicação.</p><?php endif;?><?php v5foot();?>
